import json
import re

class Attr:
    def __init__(self, identifier="", classes=None, key_vals=None):
        self.identifier = identifier
        self.classes = classes if classes is not None else []
        self.key_vals = key_vals if key_vals is not None else []

    def to_json(self):
        return [self.identifier, self.classes, [[k, v] for k, v in self.key_vals]]

    @staticmethod
    def from_json(data):
        if not data or not isinstance(data, list) or len(data) < 3:
            return Attr()
        ident = data[0]
        classes = data[1] if isinstance(data[1], list) else []
        kvs = [[kv[0], kv[1]] for kv in data[2]] if isinstance(data[2], list) else []
        return Attr(ident, classes, kvs)

class Meta:
    def __init__(self, meta_dict=None):
        self.meta_dict = meta_dict if meta_dict is not None else {}

    def get_string(self, key):
        val = self.meta_dict.get(key)
        if val is None:
            return None
        if isinstance(val, str):
            return val
        if isinstance(val, dict):
            t = val.get("t")
            if t == "MetaString":
                return val.get("c")
            if t == "MetaInlines":
                return inlines_to_string(parse_inlines_json(val.get("c", [])))
            if t == "MetaBlocks":
                return blocks_to_string(parse_blocks_json(val.get("c", [])))
        return str(val)

    def to_json(self):
        res = {}
        for k, v in self.meta_dict.items():
            if isinstance(v, dict) and "t" in v:
                res[k] = v
            elif isinstance(v, str):
                res[k] = {"t": "MetaString", "c": v}
            elif isinstance(v, bool):
                res[k] = {"t": "MetaBool", "c": v}
            elif isinstance(v, list):
                res[k] = {"t": "MetaList", "c": [
                    {"t": "MetaInlines", "c": [{"t": "Str", "c": str(x)}]} if isinstance(x, str) else x
                    for x in v
                ]}
            else:
                res[k] = {"t": "MetaString", "c": str(v)}
        return res

# Inlines
class Inline:
    pass

class Str(Inline):
    def __init__(self, text):
        self.text = text
    def to_json(self):
        return {"t": "Str", "c": self.text}

class Space(Inline):
    def to_json(self):
        return {"t": "Space"}

class SoftBreak(Inline):
    def to_json(self):
        return {"t": "SoftBreak"}

class LineBreak(Inline):
    def to_json(self):
        return {"t": "LineBreak"}

class Emph(Inline):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Emph", "c": [x.to_json() for x in self.content]}

class Strong(Inline):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Strong", "c": [x.to_json() for x in self.content]}

class Strikeout(Inline):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Strikeout", "c": [x.to_json() for x in self.content]}

class Superscript(Inline):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Superscript", "c": [x.to_json() for x in self.content]}

class Subscript(Inline):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Subscript", "c": [x.to_json() for x in self.content]}

class Code(Inline):
    def __init__(self, attr, code):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.code = code
    def to_json(self):
        return {"t": "Code", "c": [self.attr.to_json(), self.code]}

class Math(Inline):
    def __init__(self, math_type, code):
        self.math_type = math_type # "InlineMath" or "DisplayMath"
        self.code = code
    def to_json(self):
        return {"t": "Math", "c": [{"t": self.math_type}, self.code]}

class Link(Inline):
    def __init__(self, attr, content, target):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.content = content # list of Inlines
        self.target = target # [url, title]
    def to_json(self):
        return {"t": "Link", "c": [self.attr.to_json(), [x.to_json() for x in self.content], self.target]}

class Image(Inline):
    def __init__(self, attr, content, target):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.content = content # list of Inlines (alt text)
        self.target = target # [url, title]
    def to_json(self):
        return {"t": "Image", "c": [self.attr.to_json(), [x.to_json() for x in self.content], self.target]}

class RawInline(Inline):
    def __init__(self, fmt, text):
        self.fmt = fmt
        self.text = text
    def to_json(self):
        return {"t": "RawInline", "c": [self.fmt, self.text]}

class Note(Inline):
    def __init__(self, content):
        self.content = content # list of Blocks
    def to_json(self):
        return {"t": "Note", "c": [x.to_json() for x in self.content]}

class Span(Inline):
    def __init__(self, attr, content):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.content = content
    def to_json(self):
        return {"t": "Span", "c": [self.attr.to_json(), [x.to_json() for x in self.content]]}

# Blocks
class Block:
    pass

class Header(Block):
    def __init__(self, level, attr, content):
        self.level = level
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.content = content # list of Inlines
    def to_json(self):
        return {"t": "Header", "c": [self.level, self.attr.to_json(), [x.to_json() for x in self.content]]}

class Para(Block):
    def __init__(self, content):
        self.content = content # list of Inlines
    def to_json(self):
        return {"t": "Para", "c": [x.to_json() for x in self.content]}

class Plain(Block):
    def __init__(self, content):
        self.content = content
    def to_json(self):
        return {"t": "Plain", "c": [x.to_json() for x in self.content]}

class CodeBlock(Block):
    def __init__(self, attr, code):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.code = code
    def to_json(self):
        return {"t": "CodeBlock", "c": [self.attr.to_json(), self.code]}

class RawBlock(Block):
    def __init__(self, fmt, text):
        self.fmt = fmt
        self.text = text
    def to_json(self):
        return {"t": "RawBlock", "c": [self.fmt, self.text]}

class BlockQuote(Block):
    def __init__(self, content):
        self.content = content # list of Blocks
    def to_json(self):
        return {"t": "BlockQuote", "c": [x.to_json() for x in self.content]}

class BulletList(Block):
    def __init__(self, items):
        self.items = items # list of list of Blocks
    def to_json(self):
        return {"t": "BulletList", "c": [[[b.to_json() for b in item] for item in self.items]]}

class OrderedList(Block):
    def __init__(self, list_attr, items):
        self.list_attr = list_attr # [start_num, style, delim]
        self.items = items
    def to_json(self):
        num = self.list_attr[0] if self.list_attr else 1
        style = {"t": "Decimal"}
        delim = {"t": "Period"}
        return {"t": "OrderedList", "c": [[num, style, delim], [[b.to_json() for b in item] for item in self.items]]}

class HorizontalRule(Block):
    def to_json(self):
        return {"t": "HorizontalRule"}

class Div(Block):
    def __init__(self, attr, content):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.content = content
    def to_json(self):
        return {"t": "Div", "c": [self.attr.to_json(), [x.to_json() for x in self.content]]}

class Table(Block):
    def __init__(self, attr, caption, colspec, head, bodies, foot):
        self.attr = attr if isinstance(attr, Attr) else Attr()
        self.caption = caption
        self.colspec = colspec
        self.head = head
        self.bodies = bodies
        self.foot = foot
    def to_json(self):
        return {"t": "Table", "c": [
            self.attr.to_json(),
            self.caption if self.caption else [None, []],
            self.colspec if self.colspec else [],
            self.head if self.head else [["",[],[]], []],
            self.bodies if self.bodies else [],
            self.foot if self.foot else [["",[],[]], []]
        ]}

class Document:
    def __init__(self, blocks=None, meta=None):
        self.blocks = blocks if blocks is not None else []
        self.meta = meta if meta is not None else Meta()
        self.api_version = [1, 23, 1, 2]

    def to_json(self):
        return {
            "pandoc-api-version": self.api_version,
            "meta": self.meta.to_json(),
            "blocks": [b.to_json() for b in self.blocks]
        }

def inlines_to_string(inlines):
    res = []
    for inl in inlines:
        if isinstance(inl, Str):
            res.append(inl.text)
        elif isinstance(inl, (Space, SoftBreak)):
            res.append(" ")
        elif isinstance(inl, LineBreak):
            res.append("\n")
        elif isinstance(inl, (Emph, Strong, Strikeout, Superscript, Subscript, Span, Link)):
            res.append(inlines_to_string(inl.content))
        elif isinstance(inl, Code):
            res.append(inl.code)
        elif isinstance(inl, Math):
            res.append(inl.code)
    return "".join(res)

def blocks_to_string(blocks):
    res = []
    for b in blocks:
        if isinstance(b, (Para, Plain, Header)):
            res.append(inlines_to_string(b.content))
        elif isinstance(b, CodeBlock):
            res.append(b.code)
        elif isinstance(b, BlockQuote):
            res.append(blocks_to_string(b.content))
        elif isinstance(b, Div):
            res.append(blocks_to_string(b.content))
        elif isinstance(b, BulletList):
            for item in b.items:
                res.append(blocks_to_string(item))
        elif isinstance(b, OrderedList):
            for item in b.items:
                res.append(blocks_to_string(item))
    return "\n\n".join(res)

def parse_inline_json(obj):
    if not isinstance(obj, dict):
        return Str(str(obj))
    t = obj.get("t")
    c = obj.get("c")
    if t == "Str":
        return Str(c)
    if t == "Space":
        return Space()
    if t == "SoftBreak":
        return SoftBreak()
    if t == "LineBreak":
        return LineBreak()
    if t == "Emph":
        return Emph(parse_inlines_json(c))
    if t == "Strong":
        return Strong(parse_inlines_json(c))
    if t == "Strikeout":
        return Strikeout(parse_inlines_json(c))
    if t == "Superscript":
        return Superscript(parse_inlines_json(c))
    if t == "Subscript":
        return Subscript(parse_inlines_json(c))
    if t == "Code":
        attr = Attr.from_json(c[0])
        return Code(attr, c[1])
    if t == "Math":
        mtype = c[0].get("t", "InlineMath")
        return Math(mtype, c[1])
    if t == "Link":
        attr = Attr.from_json(c[0])
        content = parse_inlines_json(c[1])
        target = c[2]
        return Link(attr, content, target)
    if t == "Image":
        attr = Attr.from_json(c[0])
        content = parse_inlines_json(c[1])
        target = c[2]
        return Image(attr, content, target)
    if t == "RawInline":
        return RawInline(c[0], c[1])
    if t == "Note":
        return Note(parse_blocks_json(c[0]))
    if t == "Span":
        attr = Attr.from_json(c[0])
        return Span(attr, parse_inlines_json(c[1]))
    return Str("")

def parse_inlines_json(arr):
    if not isinstance(arr, list):
        return []
    return [parse_inline_json(x) for x in arr]

def parse_block_json(obj):
    if not isinstance(obj, dict):
        return Plain([])
    t = obj.get("t")
    c = obj.get("c")
    if t == "Header":
        level = c[0]
        attr = Attr.from_json(c[1])
        content = parse_inlines_json(c[2])
        return Header(level, attr, content)
    if t == "Para":
        return Para(parse_inlines_json(c))
    if t == "Plain":
        return Plain(parse_inlines_json(c))
    if t == "CodeBlock":
        attr = Attr.from_json(c[0])
        return CodeBlock(attr, c[1])
    if t == "RawBlock":
        return RawBlock(c[0], c[1])
    if t == "BlockQuote":
        return BlockQuote(parse_blocks_json(c))
    if t == "BulletList":
        items = [[parse_block_json(b) for b in item] for item in c]
        return BulletList(items)
    if t == "OrderedList":
        lattr = c[0]
        items = [[parse_block_json(b) for b in item] for item in c[1]]
        return OrderedList(lattr, items)
    if t == "HorizontalRule":
        return HorizontalRule()
    if t == "Div":
        attr = Attr.from_json(c[0])
        content = parse_blocks_json(c[1])
        return Div(attr, content)
    return Plain([])

def parse_blocks_json(arr):
    if not isinstance(arr, list):
        return []
    return [parse_block_json(x) for x in arr]

def document_from_json(data):
    if isinstance(data, str):
        data = json.loads(data)
    blocks_data = data.get("blocks", [])
    meta_data = data.get("meta", {})
    blocks = parse_blocks_json(blocks_data)
    meta = Meta(meta_data)
    doc = Document(blocks, meta)
    if "pandoc-api-version" in data:
        doc.api_version = data["pandoc-api-version"]
    return doc
EOF"}

