import re

def render_template(template_text, context):
    """
    Renders a Pandoc template with context dictionary.
    context keys map to string, list, bool, or callable/dict.
    """
    lines = template_text.splitlines(keepends=True)
    out = []
    i = 0
    n = len(lines)

    # Process template line by line or token by token
    full_text = template_text
    return process_template_str(full_text, context)

def evaluate_path(var_name, context):
    # Handle method calls like styles.html()
    if var_name.endswith("()"):
        base_name = var_name[:-2]
        val = evaluate_path(base_name, context)
        return val

    parts = var_name.split(".")
    curr = context
    for p in parts:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr

def is_truthy(val):
    if val is None or val is False or val == "" or val == [] or val == {}:
        return False
    return True

def process_template_str(text, context):
    # Tokenize control structures: $if(var)$, $else$, $endif$, $for(var)$, $sep$, $endfor$
    pattern = re.compile(r'\$(?:if\(([^)]+)\)|elseif\(([^)]+)\)|else|endif|for\(([^)]+)\)|sep|endfor|--[^\n]*|\{([^}]+)\}|([a-zA-A0-9_\.\-]+(?:\(\))?))\$')

    pos = 0
    result = []
    stack = [] # for handling blocks

    # We use a recursive function / parser for template control structures
    tokens = []
    for m in pattern.finditer(text):
        start, end = m.span()
        if start > pos:
            tokens.append(('TEXT', text[pos:start]))
        pos = end

        raw = m.group(0)
        if raw.startswith('$--'):
            continue # comment
        elif raw.startswith('$if('):
            tokens.append(('IF', m.group(1)))
        elif raw.startswith('$elseif('):
            tokens.append(('ELSEIF', m.group(2)))
        elif raw == '$else$':
            tokens.append(('ELSE', None))
        elif raw == '$endif$':
            tokens.append(('ENDIF', None))
        elif raw.startswith('$for('):
            tokens.append(('FOR', m.group(3)))
        elif raw == '$sep$':
            tokens.append(('SEP', None))
        elif raw == '$endfor$':
            tokens.append(('ENDFOR', None))
        else:
            var = m.group(4) or m.group(5)
            tokens.append(('VAR', var))

    if pos < len(text):
        tokens.append(('TEXT', text[pos:]))

    out_str, _ = render_tokens(tokens, 0, context)
    return out_str

def render_tokens(tokens, idx, context):
    res = []
    i = idx
    n = len(tokens)

    while i < n:
        tok_type, val = tokens[i]

        if tok_type == 'TEXT':
            res.append(val)
            i += 1
        elif tok_type == 'VAR':
            v_val = evaluate_path(val, context)
            if v_val is not None and v_val is not False:
                if isinstance(v_val, list):
                    res.append("\n".join(str(x) for x in v_val if x is not None and x is not False))
                else:
