import re

def render_template(template_text, context):
    return process_template_str(template_text, context)

def evaluate_path(var_name, context):
    if not var_name:
        return None
    if var_name.endswith("()"):
        base_name = var_name[:-2]
        val = evaluate_path(base_name, context)
        return val

    parts = var_name.split(".")
    curr = context
    for p in parts:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr

def is_truthy(val):
    if val is None or val is False or val == "" or val == [] or val == {}:
        return False
    return True

def tokenize(text):
    pattern = re.compile(
        r'\$('
        r'(?:if\((?P<if>[^)]+)\))|'
        r'(?:elseif\((?P<elseif>[^)]+)\))|'
        r'(?P<else>else)|'
        r'(?P<endif>endif)|'
        r'(?:for\((?P<for>[^)]+)\))|'
        r'(?P<sep>sep)|'
        r'(?P<endfor>endfor)|'
        r'(?P<comment>--[^\n]*)|'
        r'(?:\{(?P<brvar>[^}]+)\})|'
        r'(?P<var>[a-zA-Z0-9_\.\-]+(?:\(\))?)'
        r')\$'
    )

    tokens = []
    pos = 0
    for m in pattern.finditer(text):
        start, end = m.span()
        if start > pos:
            tokens.append(('TEXT', text[pos:start]))
        pos = end

        gd = m.groupdict()
        if gd.get('comment'):
            continue
        elif gd.get('if'):
            tokens.append(('IF', gd['if']))
        elif gd.get('elseif'):
            tokens.append(('ELSEIF', gd['elseif']))
        elif gd.get('else'):
            tokens.append(('ELSE', None))
        elif gd.get('endif'):
            tokens.append(('ENDIF', None))
        elif gd.get('for'):
            tokens.append(('FOR', gd['for']))
        elif gd.get('sep'):
            tokens.append(('SEP', None))
        elif gd.get('endfor'):
            tokens.append(('ENDFOR', None))
        else:
            v = gd.get('brvar') or gd.get('var')
            tokens.append(('VAR', v))

    if pos < len(text):
        tokens.append(('TEXT', text[pos:]))
    return tokens

def process_template_str(text, context):
    tokens = tokenize(text)
    out_str, _ = render_tokens(tokens, 0, context)
    return out_str

def render_tokens(tokens, idx, context):
    res = []
    i = idx
    n = len(tokens)

    while i < n:
        tok_type, val = tokens[i]

        if tok_type == 'TEXT':
            res.append(val)
            i += 1
        elif tok_type == 'VAR':
            v_val = evaluate_path(val, context)
            if v_val is not None and v_val is not False:
                if isinstance(v_val, list):
                    res.append("\n".join(str(x) for x in v_val if x is not None and x is not False))
                else:
                    res.append(str(v_val))
            i += 1
        elif tok_type == 'IF':
            condition_met = is_truthy(evaluate_path(val, context))
            i += 1
            while i < n:
                tt, tv = tokens[i]
                if tt == 'ENDIF':
                    i += 1
                    break
                elif tt in ('ELSE', 'ELSEIF'):
