import html
import re
from pandoc.ast import (
    Header, Para, Plain, CodeBlock, RawBlock, BlockQuote,
    BulletList, OrderedList, HorizontalRule, Div, Table,
    Str, Space, SoftBreak, LineBreak, Emph, Strong, Strikeout, Superscript, Subscript,
    Code, Math, Link, Image, RawInline, Note, Span, inlines_to_string
)

def render_inline_html(inl, options=None):
    if isinstance(inl, Str):
        return html.escape(inl.text)
    if isinstance(inl, Space):
        return " "
    if isinstance(inl, SoftBreak):
        return "\n"
    if isinstance(inl, LineBreak):
        return "<br />\n"
    if isinstance(inl, Emph):
        return "<em>" + render_inlines_html(inl.content, options) + "</em>"
    if isinstance(inl, Strong):
        return "<strong>" + render_inlines_html(inl.content, options) + "</strong>"
    if isinstance(inl, Strikeout):
        return "<del>" + render_inlines_html(inl.content, options) + "</del>"
    if isinstance(inl, Superscript):
        return "<sup>" + render_inlines_html(inl.content, options) + "</sup>"
    if isinstance(inl, Subscript):
        return "<sub>" + render_inlines_html(inl.content, options) + "</sub>"
    if isinstance(inl, Code):
        cls_str = f' class="{" ".join(inl.attr.classes)}"' if inl.attr.classes else ""
        return f'<code{cls_str}>' + html.escape(inl.code) + "</code>"
    if isinstance(inl, Math):
        math_mode = getattr(options, 'math_mode', None) if options else None
        if math_mode == 'katex':
            return f'<span class="math inline">{html.escape(inl.code)}</span>'
        elif math_mode == 'mathml':
            return f'<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>{html.escape(inl.code)}</mi></semantics></math>'
        else:
            return f'<span class="math inline">\\({html.escape(inl.code)}\\)</span>'
    if isinstance(inl, Link):
        url, title = inl.target[0], inl.target[1]
        t_attr = f' title="{html.escape(title)}"' if title else ""
        return f'<a href="{html.escape(url)}"{t_attr}>' + render_inlines_html(inl.content, options) + "</a>"
    if isinstance(inl, Image):
        url, title = inl.target[0], inl.target[1]
        alt = html.escape(inlines_to_string(inl.content))
        t_attr = f' title="{html.escape(title)}"' if title else ""
        return f'<img src="{html.escape(url)}" alt="{alt}"{t_attr} />'
    if isinstance(inl, RawInline):
        return inl.text
    if isinstance(inl, Span):
        cls_str = f' class="{" ".join(inl.attr.classes)}"' if inl.attr.classes else ""
        id_str = f' id="{inl.attr.identifier}"' if inl.attr.identifier else ""
        return f'<span{id_str}{cls_str}>' + render_inlines_html(inl.content, options) + "</span>"
    if isinstance(inl, Note):
        # Footnote reference anchor
        fn_num = getattr(options, 'curr_fn_num', 1) if options else 1
        if options:
            options.curr_fn_num = fn_num + 1
            if not hasattr(options, 'collected_notes'):
                options.collected_notes = []
            options.collected_notes.append((fn_num, inl.content))
        return f'<a href="#fn{fn_num}" class="footnote-ref" id="fnref{fn_num}" role="doc-noteref"><sup>{fn_num}</sup></a>'
    return ""

def render_inlines_html(inlines, options=None):
    return "".join(render_inline_html(x, options) for x in inlines)

def render_block_html(block, options=None, cb_counter=1):
    if isinstance(block, Header):
        level = block.level
        if options and hasattr(options, 'shift_heading_level_by') and options.shift_heading_level_by:
            level = max(1, min(6, level + options.shift_heading_level_by))

        id_str = f' id="{block.attr.identifier}"' if block.attr.identifier else ""
        num_str = ""
        if options and getattr(options, 'number_sections', False):
            # Calculate section number
            if not hasattr(options, 'section_nums'):
                options.section_nums = [0] * 6
            options.section_nums[level-1] += 1
            for k in range(level, 6):
                options.section_nums[k] = 0
            s_num = ".".join(str(x) for x in options.section_nums[:level] if x > 0)
            num_str = f' data-number="{s_num}"'
            body = f'<span class="header-section-number">{s_num}</span> ' + render_inlines_html(block.content, options)
        else:
            body = render_inlines_html(block.content, options)

        return f'<h{level}{num_str}{id_str}>{body}</h{level}>\n'

