        code_text = html.escape(block.code)
        lang = block.attr.classes[0] if block.attr.classes else ""

        syntax_highlighting = getattr(options, 'syntax_highlighting', 'default') if options else 'default'
        if syntax_highlighting == 'none' or not lang:
            cls_str = f' class="{lang}"' if lang else ""
            return f'<pre{cls_str}><code>{code_text}</code></pre>\n'

        # Highlight code block
        cb_id = f'cb{cb_counter}'
        return f'<div class="sourceCode" id="{cb_id}"><pre class="sourceCode {lang}"><code class="sourceCode {lang}"><span id="{cb_id}-1"><a href="#{cb_id}-1" aria-hidden="true" tabindex="-1"></a>{code_text}</span></code></pre></div>\n'

    if isinstance(block, RawBlock):
        return block.text + "\n"

    if isinstance(block, BlockQuote):
        inner = "".join(render_block_html(b, options) for b in block.content)
        return f'<blockquote>\n{inner}</blockquote>\n'

    if isinstance(block, BulletList):
        items_html = []
        is_task_list = False
        for item in block.items:
            item_content = "".join(render_block_html(b, options) for b in item)
            if '<input type="checkbox"' in item_content or 'task-list' in item_content:
                is_task_list = True
            items_html.append(f'<li>{item_content.strip()}</li>\n')

        list_cls = ' class="task-list"' if is_task_list else ""
        return f'<ul{list_cls}>\n' + "".join(items_html) + '</ul>\n'

    if isinstance(block, OrderedList):
        start = block.list_attr[0] if block.list_attr else 1
        type_str = f' type="1"' if start == 1 else f' start="{start}"'
        items_html = []
        for item in block.items:
            item_content = "".join(render_block_html(b, options) for b in item)
            items_html.append(f'<li>{item_content.strip()}</li>\n')
        return f'<ol{type_str}>\n' + "".join(items_html) + 'dylib' if False else f'<ol{type_str}>\n' + "".join(items_html) + '</ol>\n'

    if isinstance(block, HorizontalRule):
        return '<hr />\n'

    if isinstance(block, Div):
        id_str = f' id="{block.attr.identifier}"' if block.attr.identifier else ""
        cls_str = f' class="{" ".join(block.attr.classes)}"' if block.attr.classes else ""
        inner = "".join(render_block_html(b, options) for b in block.content)
        return f'<div{id_str}{cls_str}>\n{inner}</div>\n'

    if isinstance(block, Table):
        rows = []
        if block.head and len(block.head) > 1 and block.head[1]:
            # Header row
            h_cells = []
            for col in block.head[1][0][1]:
                c_html = "".join(render_block_html(b, options) for b in col[4]).strip()
                h_cells.append(f'<th>{c_html}</th>\n')
            rows.append('<thead>\n<tr>\n' + "".join(h_cells) + '</tr>\n</thead>\n')

        body_rows = []
        if block.bodies:
            for b in block.bodies:
                for row in b[3]:
                    r_cells = []
                    for col in row[1]:
                        c_html = "".join(render_block_html(b, options) for b in col[4]).strip()
                        r_cells.append(f'<td>{c_html}</td>\n')
                    body_rows.append('<tr>\n' + "".join(r_cells) + '</tr>\n')
        rows.append('<tbody>\n' + "".join(body_rows) + 'tbody>\n')
        return '<table>\n' + "".join(rows) + '</table>\n'

    return ""

def build_toc_html(doc, options=None):
    headers = [b for b in doc.blocks if isinstance(b, Header)]
    if not headers:
        return ""

    res = ['<ul>\n']
    curr_level = 1
    for h in headers:
        lvl = h.level
        title = render_inlines_html(h.content, options)
        ident = h.attr.identifier

        if lvl > curr_level:
            res.append('<ul>\n' * (lvl - curr_level))
            curr_level = lvl
        elif lvl < curr_level:
            res.append('</ul>\n' * (curr_level - lvl))
            curr_level = lvl

        res.append(f'<li><a href="#{ident}" id="toc-{ident}">{title}</a>')
        res.append('</li>\n')

    if curr_level > 1:
        res.append('</ul>\n' * (curr_level - 1))
    res.append('</ul>\n')
    return "".join(res)

def write_html(doc, options=None):
    if options:
        options.curr_fn_num = 1
        options.collected_notes = []
        options.section_nums = [0] * 6

    body_blocks = []
    cb_counter = 1
    for b in doc.blocks:
        body_blocks.append(render_block_html(b, options, cb_counter))
        if isinstance(b, CodeBlock):
            cb_counter += 1

    # Render collected footnotes if any
    notes_html = ""
    if options and getattr(options, 'collected_notes', None):
        fn_items = []
        for fn_num, fn_blocks in options.collected_notes:
            fn_b_html = "".join(render_block_html(b, options) for b in fn_blocks).strip()
            backlink = f'<a href="#fnref{fn_num}" class="footnote-back" role="doc-backlink">↩︎</a>'
            if fn_b_html.endswith('</p>'):
                fn_b_html = fn_b_html[:-4] + backlink + '</p>'
            else:
                fn_b_html += backlink
            fn_items.append(f'<li id="fn{fn_num}">{fn_b_html}</li>\n')

        notes_html = (
            '<section id="footnotes" class="footnotes footnotes-end-of-document" role="doc-endnotes">\n'
            '<hr />\n'
            '<ol>\n' + "".join(fn_items) + '</ol>\n'
            '</section>\n'
        )

    body_html = "".join(body_blocks) + notes_html

    return body_html
