import html
from pandoc.ast import (
    Header, Para, Plain, CodeBlock, RawBlock, BlockQuote,
    BulletList, OrderedList, HorizontalRule, Div, Table,
    Str, Space, SoftBreak, LineBreak, Emph, Strong, Strikeout, Superscript, Subscript,
    Code, Math, Link, Image, RawInline, Note, Span, inlines_to_string
)

def render_inline_docbook(inl, options=None):
    if isinstance(inl, Str):
        return html.escape(inl.text)
    if isinstance(inl, Space):
        return " "
    if isinstance(inl, SoftBreak):
        return "\n"
    if isinstance(inl, LineBreak):
        return "\n"
    if isinstance(inl, Emph):
        return "<emphasis>" + render_inlines_docbook(inl.content, options) + "</emphasis>"
    if isinstance(inl, Strong):
        return '<emphasis role="strong">' + render_inlines_docbook(inl.content, options) + "</emphasis>"
    if isinstance(inl, Code):
        return "<literal>" + html.escape(inl.code) + "</literal>"
    if isinstance(inl, Link):
        label = render_inlines_docbook(inl.content, options)
        url = inl.target[0]
        return f'<link xlink:href="{html.escape(url)}">{label}</link>'
    return ""

def render_inlines_docbook(inlines, options=None):
    return "".join(render_inline_docbook(x, options) for x in inlines)

def render_block_docbook(block, options=None):
    if isinstance(block, Header):
        title = render_inlines_docbook(block.content, options)
        id_attr = f' xml:id="{block.attr.identifier}"' if block.attr.identifier else ""
        return f'<section{id_attr}>\n  <title>{title}</title>\n'

    if isinstance(block, Para):
        return f'  <para>\n    {render_inlines_docbook(block.content, options)}\n  </para>\n'

    if isinstance(block, Plain):
        return render_inlines_docbook(block.content, options) + "\n"

    if isinstance(block, CodeBlock):
        return f'  <programlisting>{html.escape(block.code)}</programlisting>\n'

    if isinstance(block, BulletList):
        items_xml = []
        for item in block.items:
            item_str = "".join(render_block_docbook(b, options) for b in item).strip()
            items_xml.append(f'  <listitem>\n    {item_str}\n  </listitem>')
        return '<itemizedlist spacing="compact">\n' + "\n".join(items_xml) + '\n</itemizedlist>\n'

    return ""

def write_docbook(doc, options=None):
