from pandoc.ast import (
    Header, Para, Plain, CodeBlock, RawBlock, BlockQuote,
    BulletList, OrderedList, HorizontalRule, Div, Table,
    Str, Space, SoftBreak, LineBreak, Emph, Strong, Strikeout, Superscript, Subscript,
    Code, Math, Link, Image, RawInline, Note, Span
)

def format_inline_native(inl):
    if isinstance(inl, Str):
        return f'Str "{inl.text}"'
    if isinstance(inl, Space):
        return 'Space'
    if isinstance(inl, SoftBreak):
        return 'SoftBreak'
    if isinstance(inl, LineBreak):
        return 'LineBreak'
    if isinstance(inl, Emph):
        return f'Emph [ {", ".join(format_inline_native(x) for x in inl.content)} ]'
    if isinstance(inl, Strong):
        return f'Strong [ {", ".join(format_inline_native(x) for x in inl.content)} ]'
    if isinstance(inl, Code):
        return f'Code ("", [], []) "{inl.code}"'
    if isinstance(inl, Link):
        url, title = inl.target[0], inl.target[1]
        lbl = ", ".join(format_inline_native(x) for x in inl.content)
        return f'Link ("", [], []) [ {lbl} ] ("{url}", "{title}")'
    return 'Space'

def format_block_native(b):
    if isinstance(b, Header):
        inls = ", ".join(format_inline_native(x) for x in b.content)
        ident = f'"{b.attr.identifier}"' if b.attr.identifier else '""'
        return f'Header {b.level} ( {ident} , [] , [] ) [ {inls} ]'
    if isinstance(b, Para):
        inls = ", ".join(format_inline_native(x) for x in b.content)
        return f'Para [ {inls} ]'
    if isinstance(b, Plain):
        inls = ", ".join(format_inline_native(x) for x in b.content)
        return f'Plain [ {inls} ]'
    if isinstance(b, CodeBlock):
        return f'CodeBlock ("", [], []) "{b.code}"'
    if isinstance(b, BulletList):
        items_str = []
        for item in b.items:
            b_str = ", ".join(format_block_native(x) for x in item)
            items_str.append(f'[ {b_str} ]')
        return f'BulletList [ {", ".join(items_str)} ]'
    return 'HorizontalRule'

def write_native(doc, options=None):
    blocks_str = ", ".join(format_block_native(b) for b in doc.blocks)
