import re
from pandoc.ast import Document, Meta, Header, Para, Plain, Str, Space, Attr

def read_native(text):
    # Basic native AST parser for simple native structures
    blocks = []
    # Match Header level ( "id" , [] , [] ) [ Str "title" ]
    for m in re.finditer(r'Header\s+(\d+)\s*\(\s*"([^"]*)"[^\]]*\]\s*\[\s*Str\s*"([^"]*)"\s*\]', text):
        lvl = int(m.group(1))
        ident = m.group(2)
        title = m.group(3)
        blocks.append(Header(lvl, Attr(ident, [], []), [Str(title)]))

    if not blocks:
        # Fallback to plain text
        blocks = [Para([Str(text.strip())])]

    return Document(blocks, Meta())
